#include <linux/key.h>
#include <linux/user_namespace.h>
#include <linux/uaccess.h>

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret;

    key = key_lookup(keyid);
    if (IS_ERR(key)) {
        return PTR_ERR(key);
    }

    if (key->flags & KEY_FLAG_NEGATIVE) {
        key_put(key);
        return -ENOKEY;
    }

    if (!is_key_readable(key)) {
        key_put(key);
        return -EACCES;
    }

    ret = key_read(key, buffer, buflen);
    if (ret < 0) {
        key_put(key);
        return ret;
    }

    key_put(key);
    return ret;
}

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret = 0;

    key = keyring_lookup_key(keyid);
    if (!key || key->negative) {
        return -ENOKEY;
    }

    if (!key_permission(current_cred(), key, KEY_NEED_READ)) {
        return -EACCES;
    }

    down_read(&key->sem);
    if (key->type->read) {
        ret = key->type->read(key, buffer, buflen);
        if (ret < 0) {
            up_read(&key->sem);
            return ret;
        }
    } else {
        ret = -EINVAL;
    }
    up_read(&key->sem);

    return ret;
}

#include <linux/key.h>
#include <linux/errno.h>
#include <linux/spinlock.h>
#include <linux/uaccess.h>

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen)
{
    struct key *key;
    long ret = 0;

    key = key_lookup(keyid);
    if (IS_ERR(key)) {
        return PTR_ERR(key);
    }

    if (key->negative) {
        key_put(key);
        return -ENOENT;
    }

    if (!key_permission(key, KEY_NEED_READ)) {
        key_put(key);
        return -EACCES;
    }

    spin_lock(&key->lock);

    if (key->datalen > buflen) {
        ret = -ERANGE;
    } else {
        if (copy_to_user(buffer, key->payload.data, key->datalen)) {
            ret = -EFAULT;
        } else {
            ret = key->datalen;
        }
    }

    spin_unlock(&key->lock);
    key_put(key);

    return ret;
}

long key_read_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret = 0;

    key = key_lookup(keyid);
    if (IS_ERR_OR_NULL(key)) {
        return PTR_ERR(key);
    }

    if (key->flags & KEY_FLAG_NEGATIVE) {
        ret = -ENOKEY;
        goto out;
    }

    if (!key_permission(current_cred(), key, KEY_NEED_READ)) {
        ret = -EACCES;
        goto out;
    }

    ret = key_read(key, buffer, buflen);
    if (ret < 0) {
        goto out;
    }

out:
    key_put(key);
    return ret;
}

#include <linux/key.h>
#include <linux/errno.h>
#include <linux/uaccess.h>
#include <linux/spinlock.h>

long read_key_value(key_serial_t keyid, char __user *buffer, size_t buflen) {
    struct key *key;
    long ret = 0;
    char *value = NULL;
    size_t valuelen = 0;

    key = key_lookup(keyid);
    if (IS_ERR(key))
        return PTR_ERR(key);

    if (key->negative)
        return -ENOKEY;

    if (!key_permission(current_cred(), key, KEY_NEED_READ))
        return -EACCES;

    ret = key_read(key, &value, &valuelen);
    if (ret < 0)
        goto out;

    if (valuelen > buflen) {
        ret = -ERANGE;
        goto out_free;
    }

    if (copy_to_user(buffer, value, valuelen)) {
        ret = -EFAULT;
        goto out_free;
    }

    ret = valuelen;

out_free:
    kfree(value);
out:
    key_put(key);
    return ret;
}
